document.addEventListener('DOMContentLoaded', function () {
  const links = document.links;
  for (let i = 0, linksLength = links.length; i < linksLength; i++) {
    if (links[i].hostname !== window.location.hostname) {
      links[i].target = '_blank';
      links[i].rel = 'noreferrer noopener';
    }
  }
});

document.addEventListener("shopify:section:load", scrollAnimations);
document.addEventListener("DOMContentLoaded", scrollAnimations);

function scrollAnimations() {
  function scrollCheck() {
    if (window.scrollY > 0) {
      document.body.classList.add("scrolled");
    } else {
      document.body.classList.remove("scrolled");
    }
  }
  window.addEventListener("scroll", scrollCheck, {
    passive: true,
  });

  // Reveal/fade in elements once they are scrolled into viewport
  const visibilityObserver = new IntersectionObserver(
    (entries) => {
      let elCount = 0;
      for (let entry of entries) {
        if (entry.isIntersecting) {
          entry.target.style.setProperty("--animation-delay", `${0 * elCount}s`);
          entry.target.classList.add("in-view");
          elCount += 1;
          visibilityObserver.unobserve(entry.target);
        }
      }
    },
    {
      rootMargin: "0px 0px -15% 0px",
    }
  );

  const animatedElements = document.querySelectorAll(
    ".js-fade-in, .template-product .product__media, .template__collection .template-collection-banner .template-collection-banner__wrapper.js-animate, .template__artist .template-artist-banner .template-artist-banner__wrapper.js-animate, .js-animate .card__container, .shopify-section.hero-banner .hero-banner__wrapper.js-animate, .shopify-section.media-section .js-animate .media-section__wrapper > .media-item, .shopify-section.media-tiles-section .js-animate .media-tile"
  );

  for (let el of animatedElements) {
    visibilityObserver.observe(el);
  }

  // Reveal/fade in product cards that are added after initial load
  const animatedProductGrids = document.querySelectorAll(".shopify-section.recommended-products, #ProductGridContainer");
  if (animatedProductGrids.length > 0) {
    const productCardObserver = new MutationObserver((mutations) => {
      for (let mutation of mutations) {
        for (let node of mutation.addedNodes) {
          if (node instanceof HTMLElement) {
            const newProductCards = node.querySelectorAll(".card__container");
            for (let card of newProductCards) {
              visibilityObserver.observe(card);
            }
          }
        }
      }
    });
    for (let productGrid of animatedProductGrids) {
      productCardObserver.observe(productGrid, {
        childList: true,
        subtree: true,
      });
    }
  }
}

document.addEventListener("DOMContentLoaded", function () {
  const blocks = document.querySelectorAll(".js-media-img-link .media-item-image-text");
  for (let block of blocks) {
    const media = block.querySelector(".media-text-image picture");
    const link = block.querySelector(".media-text-buttons .btn");
    if (media && link && link.href) {
      const newAnchor = document.createElement("a");
      newAnchor.href = link.href;
      media.parentNode.insertBefore(newAnchor, media);
      newAnchor.appendChild(media);
    }
  }
});

  document.addEventListener("DOMContentLoaded", function () {
    const products = [
      // ["PRODUCT ID", "CUSTOM TEXT"]
      ["8155061584063", "MIRADOR"],
      ["8155068661951", "MIRADOR"],
      ["8155069972671", "MIRADOR"],
      ["8160603865279", "GHOST WORLD"],
      ["8160596820159", "GHOST WORLD"],
      ["8164627972287", "GHOST WORLD"],
      ["8177385701567", "EVERYBODY SCREAM"],
      ["8177385636031", "EVERYBODY SCREAM"],
      ["8203287953599", "LXVE to DEATH (The End ver.) (Signed)"],
      ["8203276386495", "LXVE to DEATH (The End ver.)"],
      ["8203276353727", "LXVE to DEATH (Love Sick ver.)"],
      ["8203276320959", "LXVE to DEATH (Love Sick ver.) (Signed)"],
      ["8205283524799", ["Beat-Boxer (Beat ver.)", 'NEXZ\'s 3rd Mini Album "Beat-Boxer"', "1. Legacy
2. Beat-Boxer
3. I'm Him
4. Co-Star
5. Next To Me"]],
      ["8205283590335", ["Beat-Boxer (Boxer ver.)", 'NEXZ\'s 3rd Mini Album "Beat-Boxer"', "1. Legacy
2. Beat-Boxer
3. I'm Him
4. Co-Star
5. Next To Me"]],
      ["8251257520319", 'Like It’s Christmas 12"'],
      ["8258606334143", "ERROR (404) Deluxe Edition CD"],
      ["8258606301375", "ERROR (404) Deluxe Edition 2LP"],
    ];

    const artists = [
      // ["ARTIST SLUG", "CUSTOM TEXT"]
      ["mirador", "MIRADOR"],
      ["xdinary-heroes", "Xdinary Heroes"],
    ];

    for (let product of products) {
      const productID = product[0];
      const customText = product[1];
      const productTitlesAndDescriptions = document.querySelectorAll(
        `.card__wrapper[data-product="${productID}"] .card__title p, .product_card[data-product="${productID}"] .card__title p, #cart-upsell-item--${productID} .cart-upsell__item-prompt, .cart__item[data-product="${productID}"] .cart__item__title_clamp, .template-product__wrapper[data-product="${productID}"] .product-title, .template-product__wrapper[data-product="${productID}"] .accordion__content`
      );
      for (let productTitleOrDescription of productTitlesAndDescriptions) {
        undoTextTransform(productTitleOrDescription, customText);
      }

      const productWrappers = document.querySelectorAll(`.template-product__wrapper[data-product="${productID}"]`);
      const productWrapperObserver = new MutationObserver((mutations) => {
        for (let mutation of mutations) {
          for (let node of mutation.addedNodes) {
            if (node instanceof HTMLElement) {
              if (node.classList.contains("product-title")) {
                undoTextTransform(node, customText);
              }
              const descriptions = node.querySelectorAll(".accordion__content");
              for (let description of descriptions) {
                undoTextTransform(description, customText);
              }
              if (node.parentNode && node.parentNode.classList.contains("product-form__error-message")) {
                undoTextTransform(node, customText);
              }
            }
          }
        }
      });
      for (let productWrapper of productWrappers) {
        productWrapperObserver.observe(productWrapper, {
          childList: true,
          subtree: true,
        });
      }
    }

    const productGrids = document.querySelectorAll(".shopify-section.recommended-products, #ProductGridContainer, .cart-drawer, .template__cart #MainContent > .shopify-section[id$='cart']");
    const productGridObserver = new MutationObserver((mutations) => {
      for (let mutation of mutations) {
        for (let node of mutation.addedNodes) {
          if (node instanceof HTMLElement) {
            for (let product of products) {
              const productID = product[0];
              const customText = product[1];
              const productTitles = node.querySelectorAll(
                `.product_card[data-product="${productID}"] .card__title p, #cart-upsell-item--${productID} .cart-upsell__item-prompt, .cart__item[data-product="${productID}"] .cart__item__title_clamp`
              );
              for (let productTitle of productTitles) {
                undoTextTransform(productTitle, customText);
              }
            }
          }
        }
      }
    });
    for (let productGrid of productGrids) {
      productGridObserver.observe(productGrid, {
        childList: true,
        subtree: true,
      });
    }

    for (let artist of artists) {
      const artistSlug = artist[0];
      const customText = artist[1];
      const metaobjectCardTitles = document.querySelectorAll(`.metaobject-card--artist[data-item="${artistSlug}"] .card__title p`);
      for (let metaobjectCardTitle of metaobjectCardTitles) {
        undoTextTransform(metaobjectCardTitle, customText);
      }
      if (window.location.href.includes(artistSlug)) {
        const artistPageTitles = document.querySelectorAll(".template-artist-banner__container h1, .template-collection-banner__container h1");
        for (let artistPageTitle of artistPageTitles) {
          undoTextTransform(artistPageTitle, customText);
        }
      }
    }

    function undoTextTransform(textEl, customText) {
      function replaceText(textEl, customText) {
        const textElHTML = textEl.innerHTML;
        if (textElHTML.indexOf(customText) !== -1) {
          textEl.innerHTML = textElHTML.replaceAll(customText, `${customText}`);
        }
      }
      if (Array.isArray(customText)) {
        for (let customTextString of customText) {
          replaceText(textEl, customTextString);
        }
      } else {
        replaceText(textEl, customText);
      }
    }
  });
